import{_ as s,a0 as r,w as a,s as u,I as n,x as l,a1 as e,A as o,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"Linux 面试基础问题 - 3 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 面试基础问题 - 3 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 面试基础问题 - 3 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 面试基础问题 - 3 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/10 Linux Interview Questions and Answers for Linux Beginners – Part 3","title":"Linux 面试基础问题 - 3","tag":"201312","desc":""},"relativePath":"201312/10 Linux Interview Questions and Answers for Linux Beginners – Part 3.md","filePath":"[post].md"}'),g={name:"201312/10 Linux Interview Questions and Answers for Linux Beginners – Part 3.md"};function x(m,t,p,h,c,q){const i=r("Link");return a(),u("div",null,[t[13]||(t[13]=n("h1",{id:"linux-面试基础问题-3",tabindex:"-1"},[l("Linux 面试基础问题 - 3 "),n("a",{class:"header-anchor",href:"#linux-面试基础问题-3","aria-label":"Permalink to “Linux 面试基础问题 - 3”"},"​")],-1)),t[14]||(t[14]=n("p",null,[l("在有关"),n("strong",null,"面试问题"),l("的这一系列话题的前两篇文章中，我们收到了许多好的反馈，在此表示极大的感谢，同时，我们将延续这一系列话题。在这里，我们将再次展示"),n("strong",null,"10个问题"),l("来进行相互学习。")],-1)),n("ul",null,[n("li",null,[e(i,{href:"http://linux.cn/article-2315-1.html"},{default:o(()=>[...t[0]||(t[0]=[l("11个基本的Linux面试问题及答案 – 第一部分",-1)])]),_:1})]),n("li",null,[e(i,{href:"http://linux.cn/article-2370-1.html"},{default:o(()=>[...t[1]||(t[1]=[l("10个基本的Linux面试问题及答案 – 第二部分",-1)])]),_:1})])]),t[15]||(t[15]=d('<p><img src="http://www.tecmint.com/wp-content/uploads/2013/12/Basic-Interview-Questions-Part-3.png" alt=""></p><h3 id="q-1-你如何向你的系统中添加一个新的用户-例如-tux" tabindex="-1">Q.1. 你如何向你的系统中添加一个新的用户(例如，tux)？ <a class="header-anchor" href="#q-1-你如何向你的系统中添加一个新的用户-例如-tux" aria-label="Permalink to “Q.1. 你如何向你的系统中添加一个新的用户(例如，tux)？”">​</a></h3><ul><li>使用useradd指令</li><li>使用adduser 指令</li><li>使用linuxconf指令</li><li>以上全是</li><li>以上答案全都不对</li></ul><blockquote><p><strong>答</strong> : 以上全是，即useradd, adduser 和 linuxconf 都可向你的linux系统添加新用户。</p></blockquote><h3 id="q-2-在一个硬盘上-可能有多少主分区" tabindex="-1">Q.2. 在一个硬盘上，可能有多少主分区？ <a class="header-anchor" href="#q-2-在一个硬盘上-可能有多少主分区" aria-label="Permalink to “Q.2. 在一个硬盘上，可能有多少主分区？”">​</a></h3><ul><li>1</li><li>2</li><li>4</li><li>16</li></ul><blockquote><p><strong>答</strong> : 一个硬盘上最多可能有4个主分区。</p></blockquote><h3 id="q-3-apache-http-的默认端口号是多少" tabindex="-1">Q.3. Apache/Http 的默认端口号是多少？ <a class="header-anchor" href="#q-3-apache-http-的默认端口号是多少" aria-label="Permalink to “Q.3. Apache/Http 的默认端口号是多少？”">​</a></h3><ul><li>8080</li><li>80</li><li>8443</li><li>91</li><li>以上答案全都不对</li></ul><blockquote><p><strong>答</strong> : Apache/Http默认配置是<strong>80</strong>端口</p></blockquote><h3 id="q-4-gnu代表什么" tabindex="-1">Q.4. GNU代表什么？ <a class="header-anchor" href="#q-4-gnu代表什么" aria-label="Permalink to “Q.4. GNU代表什么？”">​</a></h3><ul><li>GNU&#39;s not Unix</li><li>General Unix</li><li>General Noble Unix</li><li>Greek Needed Unix</li><li>以上答案全都不对</li></ul><blockquote><p><strong>答</strong> : GNU意为<strong>GNU&#39;s not Unix</strong>.</p></blockquote><h3 id="q-5-如果你在shell提示符中输入mysql并得到-can-t-connect-to-local-mysql-server-through-socket-var-mysql-mysql-sock-的提示-你首先应该检查什么" tabindex="-1">Q.5. 如果你在shell提示符中输入mysql并得到“can’t connect to local MySQL server through socket ‘/var/mysql/mysql.sock’ ”的提示，你首先应该检查什么？ <a class="header-anchor" href="#q-5-如果你在shell提示符中输入mysql并得到-can-t-connect-to-local-mysql-server-through-socket-var-mysql-mysql-sock-的提示-你首先应该检查什么" aria-label="Permalink to “Q.5. 如果你在shell提示符中输入mysql并得到“can’t connect to local MySQL server through socket ‘/var/mysql/mysql.sock’ ”的提示，你首先应该检查什么？”">​</a></h3><blockquote><p><strong>答</strong> : 看到这条错误消息，我首先会使用<strong>service mysql status</strong>或者<strong>service mysqld status</strong>指令来检查mysql服务是否正在运行。如果mysql服务没有运行，就启动所需服务。</p></blockquote><p><strong>注意</strong>:上面的错误消息可能是由于<strong>my.cnf</strong>或者mysql的<strong>用户权限</strong>错误配置导致的。如果启动mysql服务之后仍不管用，你需要检查这两项。</p><h3 id="q-6-如何将windows-ntfs分区挂载到linux上面" tabindex="-1">Q.6. 如何将windows ntfs分区挂载到Linux上面？ <a class="header-anchor" href="#q-6-如何将windows-ntfs分区挂载到linux上面" aria-label="Permalink to “Q.6. 如何将windows ntfs分区挂载到Linux上面？”">​</a></h3><blockquote><p><strong>答</strong> : 首先，使用<strong>apt</strong>或者<strong>yum</strong>工具安装ntfs3g包，然后使用 “<strong>sudo mount ­t ntfs­3g /dev/&lt;Windows ntfs的分区号&gt; /&lt;挂载点­&gt;</strong>” 命令来将windows分区挂载到Linux上面</p></blockquote><h3 id="q-7-下面哪一个不是基于rpm的操作系统" tabindex="-1">Q.7. 下面哪一个不是基于RPM的操作系统？ <a class="header-anchor" href="#q-7-下面哪一个不是基于rpm的操作系统" aria-label="Permalink to “Q.7. 下面哪一个不是基于RPM的操作系统？”">​</a></h3><ul><li>RedHat Linux</li><li>Centos</li><li>Scientific Linux</li><li>Debian</li><li>Fedora</li></ul><blockquote><p><strong>答</strong> : ‘<strong>Debian</strong>’ 系统不是基于<strong>RPM</strong>的，其它的几个都是</p></blockquote><h3 id="q-8-linux中-哪一个指令用来重命名文件" tabindex="-1">Q.8. Linux中，哪一个指令用来重命名文件？ <a class="header-anchor" href="#q-8-linux中-哪一个指令用来重命名文件" aria-label="Permalink to “Q.8. Linux中，哪一个指令用来重命名文件？”">​</a></h3><ul><li>mv</li><li>ren</li><li>rename</li><li>change</li><li>以上答案全都不对</li></ul><blockquote><p><strong>答</strong> : 在Linux中，<strong>mv</strong> 指令用来重命名一个文件。例如：<strong>mv /path_to_File/original_file_name.extension /Path_to_File/New_name.extension</strong></p></blockquote><h3 id="q-9-在linux中-哪个命令用来创建并显示文件" tabindex="-1">Q.9. 在Linux中，哪个命令用来创建并显示文件？ <a class="header-anchor" href="#q-9-在linux中-哪个命令用来创建并显示文件" aria-label="Permalink to “Q.9. 在Linux中，哪个命令用来创建并显示文件？”">​</a></h3><ul><li>ed</li><li>vi</li><li>cat</li><li>nano</li><li>以上答案全都不对</li></ul><blockquote><p><strong>答</strong> : ‘<strong>cat</strong>‘ 命令用来创建并且显示文件</p></blockquote><h3 id="_10-哪层协议用于支持用户和程序-如支持密码、资源分享、文件传输和网络管理" tabindex="-1">10. 哪层协议用于支持用户和程序，如支持密码、资源分享、文件传输和网络管理？ <a class="header-anchor" href="#_10-哪层协议用于支持用户和程序-如支持密码、资源分享、文件传输和网络管理" aria-label="Permalink to “10. 哪层协议用于支持用户和程序，如支持密码、资源分享、文件传输和网络管理？”">​</a></h3><ul><li>第四层协议</li><li>第五层协议</li><li>第六层协议</li><li>第七层协议</li><li>以上答案全都不对</li></ul><blockquote><p><strong>答</strong> : ‘<strong>第七层协议</strong>‘</p></blockquote><hr>',31)),n("p",null,[t[3]||(t[3]=l("via: ",-1)),e(i,{href:"http://www.tecmint.com/linux-interview-questions-and-answers-for-linux-beginners/"},{default:o(()=>[...t[2]||(t[2]=[l("http://www.tecmint.com/linux-interview-questions-and-answers-for-linux-beginners/",-1)])]),_:1})]),n("p",null,[t[6]||(t[6]=l("译者：",-1)),e(i,{href:"https://github.com/tomatoKiller"},{default:o(()=>[...t[4]||(t[4]=[l("tomatoKiller",-1)])]),_:1}),t[7]||(t[7]=l(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:o(()=>[...t[5]||(t[5]=[l("wxy",-1)])]),_:1})]),n("p",null,[t[10]||(t[10]=l("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[l("LCTT",-1)])]),_:1}),t[11]||(t[11]=l(" 原创翻译，",-1)),e(i,{href:"http://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[l("Linux中国",-1)])]),_:1}),t[12]||(t[12]=l(" 荣誉推出",-1))])])}const w=s(g,[["render",x]]);export{k as __pageData,w as default};
